  "view": "high-level",
  "title": "Reverse Proxy Topology & Upstream Multiplexing",
  "nodes": [
    { "id": "clients", "label": "External Clients (Mobile, Web, APIs)", "type": "client" },
    { "id": "proxy", "label": "Reverse Proxy (Envoy / NGINX / HAProxy)", "type": "service" },
    { "id": "svc_a", "label": "Auth Service (Instance Pool)", "type": "processor" },
    { "id": "svc_b", "label": "Catalog Service (Instance Pool)", "type": "processor" },
    { "id": "svc_c", "label": "Payment Service (Instance Pool)", "type": "processor" }
  ],
  "edges": [
    { "from": "clients", "to": "proxy", "label": "Public HTTPS / TLS Termination" },
    { "from": "proxy", "to": "svc_a", "label": "Persistent HTTP/2 Pool (/api/v1/auth)" },
    { "from": "proxy", "to": "svc_b", "label": "Persistent HTTP/2 Pool (/api/v1/catalog)" },
    { "from": "proxy", "to": "svc_c", "label": "mTLS Pool (/api/v1/payments)" }
  ]
}
```

